CREATE OR REPLACE FUNCTION public.transition_client_to_solo(p_coach_id uuid, p_client_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_updated int; BEGIN IF p_coach_id IS NULL OR p_client_id IS NULL OR p_coach_id = p_client_id THEN RETURN jsonb_build_object('ok', false, 'error', 'invalid_pair'); END IF; IF NOT EXISTS (SELECT 1 FROM public.coach_client_links WHERE coach_id = p_coach_id AND client_id = p_client_id AND status = 'active') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF; UPDATE public.program_assignments SET status = 'paused', updated_at = now() WHERE client_id = p_client_id AND assigned_by = p_coach_id AND status = 'active'; UPDATE public.coach_client_links SET status = 'ended', updated_at = now() WHERE coach_id = p_coach_id AND client_id = p_client_id AND status = 'active'; GET DIAGNOSTICS v_updated = ROW_COUNT; IF v_updated = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF; UPDATE public.user_roles SET coaching_role = 'none', updated_at = now() WHERE user_id = p_client_id AND coaching_role = 'client'; DELETE FROM public.client_tracking_config WHERE client_id = p_client_id AND coach_id = p_coach_id; UPDATE public.user_profiles SET coach_link_ended_at = now(), solo_trial_ends_at = COALESCE(solo_trial_ends_at, now() + interval '30 days'), updated_at = now() WHERE id = p_client_id; RETURN jsonb_build_object('ok', true); END; $$; REVOKE ALL ON FUNCTION public.transition_client_to_solo(uuid, uuid) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.transition_client_to_solo(uuid, uuid) TO service_role; CREATE OR REPLACE FUNCTION public.end_coach_client_link(p_client_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_uid uuid := auth.uid(); BEGIN IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated'); END IF; IF p_client_id = v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'cannot_end_self'); END IF; RETURN public.transition_client_to_solo(v_uid, p_client_id); END; $$; REVOKE ALL ON FUNCTION public.end_coach_client_link(uuid) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.end_coach_client_link(uuid) TO authenticated;
